using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace PermissionGenerator;

/// <summary>
/// [Permission("article", "read", "write")] が付いたクラスから、
/// 認可ポリシーの登録コード・権限名の定数・権限一覧を生成する。
/// </summary>
[Generator]
public sealed class PermissionSourceGenerator : IIncrementalGenerator {
    private const string AttributeMetadataName = "PermissionSample.PermissionAttribute";

    private const string AttributeSource = """
        // <auto-generated/>
        #nullable enable
        namespace PermissionSample;

        [System.AttributeUsage(System.AttributeTargets.Class, AllowMultiple = false)]
        internal sealed class PermissionAttribute : System.Attribute {
            public PermissionAttribute(string resource, params string[] actions) {
                Resource = resource;
                Actions = actions;
            }

            public string Resource { get; }

            public string[] Actions { get; }
        }
        """;

    private static readonly DiagnosticDescriptor DuplicateResource = new(
        "PERM001",
        "権限リソース名が重複しています",
        "権限リソース '{0}' が複数のクラスに宣言されています",
        "Permission",
        DiagnosticSeverity.Error,
        true);

    private static readonly DiagnosticDescriptor InvalidName = new(
        "PERM002",
        "権限名に使用できない文字が含まれています",
        "権限名 '{0}' は使用できません。小文字英字で始まり、小文字英数字とアンダースコアのみ使用できます",
        "Permission",
        DiagnosticSeverity.Error,
        true);

    public void Initialize(IncrementalGeneratorInitializationContext context) {
        context.RegisterPostInitializationOutput(static ctx => ctx.AddSource("PermissionAttribute.g.cs", AttributeSource));

        // 値の等価性を持つタプルに変換することで、属性の内容が変わらない限りインクリメンタルにキャッシュされる。
        var permissions = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                AttributeMetadataName,
                static (node, _) => node is ClassDeclarationSyntax,
                static (ctx, _) => ToPermission(ctx))
            .Where(static p => p.Resource.Length > 0);

        context.RegisterSourceOutput(permissions.Collect(), static (ctx, items) => Emit(ctx, items));
    }

    private static (string Resource, string Actions) ToPermission(GeneratorAttributeSyntaxContext ctx) {
        var args = ctx.Attributes[0].ConstructorArguments;
        var resource = args.Length > 0 ? args[0].Value as string : null;
        if (string.IsNullOrEmpty(resource)) {
            return (string.Empty, string.Empty);
        }

        var actions = new List<string>();
        if (args.Length > 1 && args[1].Kind == TypedConstantKind.Array) {
            foreach (var value in args[1].Values) {
                if (value.Value is string action && action.Length > 0) {
                    actions.Add(action);
                }
            }
        }

        return (resource!, string.Join(",", actions));
    }

    private static void Emit(SourceProductionContext ctx, ImmutableArray<(string Resource, string Actions)> items) {
        var permissions = new SortedDictionary<string, SortedSet<string>>(StringComparer.Ordinal);

        foreach (var (resource, actions) in items) {
            if (!IsValidName(resource)) {
                ctx.ReportDiagnostic(Diagnostic.Create(InvalidName, Location.None, resource));
                continue;
            }

            if (permissions.ContainsKey(resource)) {
                ctx.ReportDiagnostic(Diagnostic.Create(DuplicateResource, Location.None, resource));
                continue;
            }

            var set = new SortedSet<string>(StringComparer.Ordinal);
            foreach (var action in actions.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)) {
                if (!IsValidName(action)) {
                    ctx.ReportDiagnostic(Diagnostic.Create(InvalidName, Location.None, action));
                    continue;
                }

                set.Add(action);
            }

            permissions[resource] = set;
        }

        ctx.AddSource("Permissions.g.cs", BuildSource(permissions));
    }

    private static string BuildSource(SortedDictionary<string, SortedSet<string>> permissions) {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("namespace PermissionSample;");
        sb.AppendLine();

        sb.AppendLine("/// <summary>[Authorize(Policy = ...)] に指定できる権限名の定数。</summary>");
        sb.AppendLine("public static class Permissions {");
        foreach (var permission in permissions) {
            sb.AppendLine($"    public static class {ToPascalCase(permission.Key)} {{");
            foreach (var action in permission.Value) {
                sb.AppendLine($"        public const string {ToPascalCase(action)} = \"{permission.Key}:{action}\";");
            }

            sb.AppendLine("    }");
        }

        sb.AppendLine("}");
        sb.AppendLine();

        sb.AppendLine("/// <summary>登録されている全権限と、ユーザーが保有する権限の取得。</summary>");
        sb.AppendLine("public static class PermissionCatalog {");
        sb.AppendLine("    public static System.Collections.Generic.IReadOnlyList<string> All { get; } = new string[] {");
        foreach (var permission in permissions) {
            foreach (var action in permission.Value) {
                sb.AppendLine($"        \"{permission.Key}:{action}\",");
            }
        }

        sb.AppendLine("    };");
        sb.AppendLine();
        sb.AppendLine("    private static readonly System.Collections.Generic.HashSet<string> Lookup = new(All, System.StringComparer.Ordinal);");
        sb.AppendLine();
        sb.AppendLine("    public static System.Collections.Generic.IReadOnlyList<string> GetGranted(System.Security.Claims.ClaimsPrincipal principal) {");
        sb.AppendLine("        var granted = new System.Collections.Generic.List<string>();");
        sb.AppendLine("        foreach (var claim in principal.Claims) {");
        sb.AppendLine("            var permission = claim.Type + \":\" + claim.Value;");
        sb.AppendLine("            if (Lookup.Contains(permission)) {");
        sb.AppendLine("                granted.Add(permission);");
        sb.AppendLine("            }");
        sb.AppendLine("        }");
        sb.AppendLine("        return granted;");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        sb.AppendLine();

        sb.AppendLine("public static class PermissionPolicyExtensions {");
        sb.AppendLine("    public static Microsoft.AspNetCore.Authorization.AuthorizationBuilder AddPermissionPolicies(this Microsoft.AspNetCore.Authorization.AuthorizationBuilder builder) {");
        foreach (var permission in permissions) {
            foreach (var action in permission.Value) {
                sb.AppendLine($"        builder.AddPolicy(\"{permission.Key}:{action}\", policy => policy.RequireClaim(\"{permission.Key}\", \"{action}\"));");
            }
        }

        sb.AppendLine("        return builder;");
        sb.AppendLine("    }");
        sb.AppendLine("}");

        return sb.ToString();
    }

    private static bool IsValidName(string name) {
        if (name.Length == 0 || name[0] < 'a' || name[0] > 'z') {
            return false;
        }

        foreach (var c in name) {
            var isValid = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_';
            if (!isValid) {
                return false;
            }
        }

        return true;
    }

    private static string ToPascalCase(string name) {
        var sb = new StringBuilder();
        foreach (var segment in name.Split(new[] { '_' }, StringSplitOptions.RemoveEmptyEntries)) {
            sb.Append(char.ToUpperInvariant(segment[0]));
            sb.Append(segment, 1, segment.Length - 1);
        }

        return sb.ToString();
    }
}
